package br.com.heroisdeplantao.servico;
import br.com.heroisdeplantao.modelo.*;import br.com.heroisdeplantao.repositorio.Repositorio;
public class ProntuarioServico{private final Repositorio<Prontuario> repositorio;public ProntuarioServico(Repositorio<Prontuario> repositorio){this.repositorio=repositorio;}public void cadastrar(Prontuario prontuario){if(repositorio.buscarPorId(prontuario.getIdProntuario()).isPresent())throw new IllegalArgumentException("Prontuário duplicado");repositorio.salvar(prontuario.getIdProntuario(),prontuario);}public void adicionarRegistro(int id,String diagnostico,String descricao){buscar(id).adicionarRegistro(diagnostico,descricao);}public Prontuario buscar(int id){return repositorio.buscarPorId(id).orElseThrow(()->new IllegalArgumentException("Prontuário inexistente"));}}
